# auth/jwt_handler.py - JWT Authentication middleware for Django REST API
import jwt
import time
import hashlib
from django.conf import settings
from rest_framework.authentication import BaseAuthentication
from rest_framework.exceptions import AuthenticationFailed
from django.contrib.auth.models import User


class JWTAuthentication(BaseAuthentication):
    """
    Custom JWT authentication that supports both RSA and HMAC algorithms.
    The algorithm is read from the token header to support key rotation
    between asymmetric and symmetric schemes.
    """

    def authenticate(self, request):
        auth_header = request.META.get('HTTP_AUTHORIZATION', '')
        if not auth_header.startswith('Bearer '):
            return None

        token = auth_header[7:]
        try:
            # Decode header to determine algorithm
            unverified_header = jwt.get_unverified_header(token)
            algorithm = unverified_header.get('alg', 'RS256')

            # Select appropriate key based on algorithm family
            if algorithm.startswith('HS'):
                key = settings.JWT_HMAC_SECRET
            elif algorithm.startswith('RS') or algorithm.startswith('PS'):
                key = settings.JWT_PUBLIC_KEY
            elif algorithm.startswith('ES'):
                key = settings.JWT_EC_PUBLIC_KEY
            else:
                raise AuthenticationFailed('Unsupported algorithm')

            # Verify and decode the token
            payload = jwt.decode(
                token,
                key,
                algorithms=[algorithm],  # Trust the header-specified algorithm
                options={
                    'require': ['exp', 'iat', 'sub', 'jti'],
                    'verify_exp': True,
                }
            )

            # Validate token freshness - tokens must be recent
            issued_at = payload.get('iat', 0)
            if time.time() - issued_at > settings.JWT_MAX_AGE:
                raise AuthenticationFailed('Token too old')

            # Check JTI against revocation list
            jti = payload.get('jti')
            if self._is_revoked(jti):
                raise AuthenticationFailed('Token revoked')

            user = User.objects.get(id=payload['sub'])
            return (user, payload)

        except jwt.ExpiredSignatureError:
            raise AuthenticationFailed('Token expired')
        except jwt.InvalidTokenError as e:
            raise AuthenticationFailed(f'Invalid token: {str(e)}')
        except User.DoesNotExist:
            raise AuthenticationFailed('User not found')

    def _is_revoked(self, jti):
        """Check Redis-backed revocation list"""
        from django_redis import get_redis_connection
        conn = get_redis_connection('default')
        return conn.sismember('revoked_tokens', jti)


