class TokenIssuer:
    """Issues new JWT tokens signed with RSA private key"""

    def __init__(self):
        self.private_key = self._load_private_key()
        self.algorithm = 'RS256'

    def _load_private_key(self):
        with open(settings.JWT_PRIVATE_KEY_PATH, 'r') as f:
            return f.read()

    def issue_token(self, user, extra_claims=None):
        import uuid
        payload = {
            'sub': user.id,
            'iat': int(time.time()),
            'exp': int(time.time()) + 60,  # 60 second expiry
            'jti': str(uuid.uuid4()),
            'roles': list(user.groups.values_list('name', flat=True)),
        }
        if extra_claims:
            payload.update(extra_claims)

        return jwt.encode(payload, self.private_key, algorithm=self.algorithm)

    def rotate_signing_key(self):
        """Called by cron every 60 seconds to rotate the signing key"""
        import subprocess
        subprocess.run(
            ['vault', 'write', '-f', 'transit/keys/jwt-signer/rotate'],
            check=True
        )
        self.private_key = self._load_private_key()
